{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && node --version && python3 --version && mkdir -p /tmp/ah-review && cat > /tmp/ah-review/check.py <<'PY'
import re, sys, os
from html.parser import HTMLParser

VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}

class Check(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]; self.ids={}; self.dups=[]; self.hrefs=[]; self.controls=[]; self.uses=[]; self.line=0
    def handle_starttag(self, tag, attrs):
        d=dict(attrs); ln=self.getpos()[0]
        if 'id' in d:
            if d['id'] in self.ids: self.dups.append((d['id'], self.ids[d['id']], ln))
            else: self.ids[d['id']]=ln
        if tag=='a' and 'href' in d: self.hrefs.append((d['href'], ln))
        if 'aria-controls' in d: self.controls.append((d['aria-controls'], ln))
        if tag=='use' and 'href' in d: self.uses.append((d['href'], ln))
        if 'aria-labelledby' in d:
            for ref in d['aria-labelledby'].split(): self.controls.append((ref, ln))
        if tag not in VOID:
            self.stack.append((tag, ln))
    def handle_startendtag(self, tag, attrs):
        d=dict(attrs); ln=self.getpos()[0]
        if 'id' in d:
            if d['id'] in self.ids: self.dups.append((d['id'], self.ids[d['id']], ln))
            else: self.ids[d['id']]=ln
    def handle_endtag(self, tag):
        if tag in VOID: return
        ln=self.getpos()[0]
        if not self.stack:
            self.errors.append(f'line {ln}: unexpected </{tag}>'); return
        if self.stack[-1][0]==tag:
            self.stack.pop()
        else:
            # find nearest
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    unclosed=[t for t,_ in self.stack[i+1:]]
                    self.errors.append(f'line {ln}: </{tag}> closes over unclosed {unclosed}')
                    del self.stack[i:]
                    break
            else:
                self.errors.append(f'line {ln}: stray </{tag}>')

def check_html(path):
    txt=open(path, encoding='utf-8').read()
