*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:14px;
  line-height:1.5;
  color:var(--ink);
  background:var(--paper);
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  overflow:hidden;
}
button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
a{color:inherit;text-decoration:none}
ul,ol,dl,dd{margin:0;padding:0;list-style:none}
h1,h2,h3,h4,p{margin:0}
svg{display:block}
:focus-visible{outline:2px solid var(--prussian);outline-offset:2px;border-radius:3px}
::selection{background:var(--amber-soft);color:var(--ink)}

*{scrollbar-width:thin;scrollbar-color:var(--line) transparent}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{
  background:var(--line);
  border:3px solid transparent;
  background-clip:content-box;
  border-radius:99px;
}
::-webkit-scrollbar-thumb:hover{background-color:var(--ink-3)}

.ic{
  width:18px;height:18px;flex:none;
  fill:none;stroke:currentColor;stroke-width:1.6;
  stroke-linecap:round;stroke-linejoin:round;
}
.mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums}
.sr-only{
  position:absolute;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;
}

/* ---------- app shell ---------- */
.app{
  display:grid;
  grid-template-columns:var(--sidebar-w) minmax(0,1fr);
  height:100dvh;
  min-height:0;
  transition:grid-template-columns .22s ease;
}
.app.trace-collapsed{grid-template-columns:var(--sidebar-w) minmax(0,1fr) 0px}
.app.trace-collapsed .trace{opacity:0;pointer-events:none;overflow:hidden}
.app.sidebar-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr)}
.app.sidebar-collapsed.trace-collapsed{grid-template-columns:var(--sidebar-rail) minmax(0,1fr) 0px}

