现在加 JS。插入到 `/* ---------- sidebar sessions ---------- */` 前。

注意 `instructionCount` 初始值。JS 会更新。

代码：
```js
  /* ---------- personal capabilities ---------- */
  var instructionText = document.getElementById('instructionText');
  var instructionCount = document.getElementById('instructionCount');
  var instructionSource = document.getElementById('instructionSource');
  var memoryList = document.getElementById('memoryList');
  var memoryCount = document.getElementById('memoryCount');
  var memorySearch = document.getElementById('memorySearch');
  var memoryEmpty = document.getElementById('memoryEmpty');

  function syncInstructionCount() {
    if (instructionText && instructionCount) {
      instructionCount.textContent = String(instructionText.value.length);
    }
  }

  function updateMemoryState() {
    if (!memoryList || !memoryCount) return;
    var items = Array.prototype.slice.call(memoryList.querySelectorAll('.cap-item'));
    var visible = items.filter(function (item) { return !item.hidden; }).length;
    memoryCount.textContent = items.length + ' 条';
    if (memoryEmpty) memoryEmpty.hidden = visible > 0;
  }

  if (instructionText) {
    syncInstructionCount();
    instructionText.addEventListener('input', syncInstructionCount);
  }

  var saveInstruction = document.getElementById('saveInstruction');
  if (saveInstruction) {
    saveInstruction.addEventListener('click', function () {
      var value = instructionText.value.trim();
      if (!value) {
        showToast('指令不能为空；如需继承平台默认，请点「恢复默认」');
        instructionText.focus();
        return;
      }
      instructionSource.textContent = '用户覆盖';
      instructionSource.className = 'st st-ok';
      showToast('指令已保存，下一轮生效');
    });
  }

  var resetInstruction = document.getElementById('resetInstruction');
  if (resetInstruction) {
    resetInstruction.addEventListener('click', function () {
      instructionText.value = '';
      syncInstructionCount();
      instructionSource.textContent = '平台默认';
      instructionSource.className = 'st st-muted';
      showToast('已恢复平台默认指令');
    });
  }

  if (memoryList) {
    memoryList.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-memory-delete]');
      if (!btn) return;
      var item = btn.closest('.cap-item');
      if (!item) return;
      item.remove();
      updateMemoryState();
      showToast('记忆已删除');
    });
    updateMemoryState();
  }

  if (memorySearch) {
    memorySearch.addEventListener('input', function () {
      var q = memorySearch.value.trim().toLowerCase();
      memoryList.querySelectorAll('.cap-item').forEach(function (item) {
        item.hidden = q !== '' && item.textContent.toLowerCase().indexOf(q) === -1;
      });
      updateMemoryState();
    });
  }

  document.querySelectorAll('[data-cap-switch]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var on = btn.classList.toggle('is-on');
      btn.setAttribute('aria-checked', String(on));
      var label = btn.getAttribute('aria-label') || '';
      btn.setAttribute('aria-label', (on ? '停用' : '启用') + label.replace(/^(停用|启用)/, ''));
      showToast(on ? '已启用' : '已停用');
    });
  });
```

注意 `memoryList.querySelectorAll` if memoryList exists. 在 memorySearch handler 中，memoryList 一定存在（同一页面）。安全。

