替换整个 agents 区块（3681-3730）为新版本。使用 old_string 从 `/* ---------- agents ---------- */` 到注册处理结束。new_string 包含：
- confirm dialog helpers
- agentFilter/filterAgents with disabled logic
- updateAgentStats
- filter buttons
- search
- switch/delete bindings
- register panel
- confirmRegister
- 初始化 updateAgentStats/filterAgents

注意 `openConfirm` 也被工作流删除使用。在 agents 区块定义，工作流区块在后面，可用（函数声明/变量已赋值，脚本顺序执行到工作流绑定在 3800+，OK）。

代码：

```js
  /* ---------- agents ---------- */
  var confirmDialog = document.getElementById('confirmDialog');
  var confirmTitle = document.getElementById('confirmTitle');
  var confirmText = document.getElementById('confirmText');
  var confirmAction = document.getElementById('confirmAction');
  var cancelConfirm = document.getElementById('cancelConfirm');
  var pendingConfirm = null;
  var confirmReturnFocus = null;

  function openConfirm(title, text, action, label) {
    pendingConfirm = action;
    confirmReturnFocus = document.activeElement;
    confirmTitle.textContent = title;
    confirmText.textContent = text;
    confirmAction.textContent = label || '确认';
    confirmDialog.classList.add('is-open');
    var dialog = confirmDialog.querySelector('.dialog');
    if (dialog) dialog.focus();
  }

  function closeConfirm() {
    confirmDialog.classList.remove('is-open');
    pendingConfirm = null;
    if (confirmReturnFocus && typeof confirmReturnFocus.focus === 'function') {
      confirmReturnFocus.focus();
    }
    confirmReturnFocus = null;
  }

  confirmAction.addEventListener('click', function () {
    var action = pendingConfirm;
    closeConfirm();
    if (action) action();
  });
  cancelConfirm.addEventListener('click', closeConfirm);
  confirmDialog.addEventListener('click', function (event) {
    if (event.target === confirmDialog) closeConfirm();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && confirmDialog.classList.contains('is-open')) closeConfirm();
  });

  var agentFilter = 'all';
  var agentQuery = '';

  function agentCards() {
    return Array.prototype.slice.call(document.querySelectorAll('.agent-card'));
  }

  function filterAgents() {
    var visible = 0;
    agentCards().forEach(function (item) {
      var health = item.getAttribute('data-health');
      var disabled = item.classList.contains('is-disabled');
      var text = item.textContent.toLowerCase();
      var matchesFilter = agentFilter === 'all' ||
        (agentFilter === 'disabled' ? disabled : (!disabled && health === agentFilter));
      var match = matchesFilter && (agentQuery === '' || text.indexOf(agentQuery) !== -1);
      item.hidden = !match;
      if (match) visible += 1;
    });
    var empty = document.getElementById('agentEmpty');
    if (empty) empty.hidden = visible > 0;
  }

  function updateAgentStats() {
    var cards = agentCards();
    var enabled = cards.filter(function (card) { return !card.classList.contains('is-disabled'); });
    var healthy = enabled.filter(function (card) { return card.getAttribute('data-health') === 'healthy'; }).length;
    var degraded = enabled.filter(function (card) { return card.getAttribute('data-health') === 'degraded'; }).length;
    var disabled = cards.length - enabled.length;
    var set = function (id, value) {
      var el = document.getElementById(id);
      if (el) el.textContent = String(value);
    };
    set('agentTotalStat', cards.length);
    set('agentHealthyStat', healthy);
    set('agentDegradedStat', degraded);
    set('agentEnabledStat', enabled.length);
    var allCount = document.querySelector('[data-agent-filter="all"] span');
    var healthyCount = document.querySelector('[data-agent-filter="healthy"] span');
    var degradedCount = document.querySelector('[data-agent-filter="degraded"] span');
    var disabledCount = document.querySelector('[data-agent-filter="disabled"] span');
    if (allCount) allCount.textContent = String(cards.length);
    if (healthyCount) healthyCount.textContent = String(healthy);
    if (degradedCount) degradedCount.textContent = String(degraded);
    if (disabledCount) disabledCount.textContent = String(disabled);
  }

  document.querySelectorAll('[data-agent-filter]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      agentFilter = btn.getAttribute('data-agent-filter');
      document.querySelectorAll('[data-agent-filter]').forEach(function (b) {
        b.classList.toggle('is-active', b === btn);
      });
      filterAgents();
    });
  });

  var agentSearch = document.getElementById('agentSearch');
  if (agentSearch) {
    agentSearch.addEventListener('input', function () {
      agentQuery = agentSearch.value.trim().toLowerCase();
      filterAgents();
    });
  }

  document.querySelectorAll('[data-agent-switch]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var card = btn.closest('.agent-card');
      if (!card) return;
      var enabled = btn.classList.toggle('is-on');
      btn.setAttribute('aria-checked', String(enabled));
      var nameEl = card.querySelector('.agent-name');
      var name = nameEl ? nameEl.textContent : '智能体';
      btn.setAttribute('aria-label', (enabled ? '停用 ' : '启用 ') + name);
      var label = card.querySelector('.agent-switch-label');
      if (label) label.textContent = enabled ? '已启用' : '已停用';
      card.classList.toggle('is-disabled', !enabled);
      updateAgentStats();
      filterAgents();
      showToast(enabled ? '已启用 ' + name : '已停用 ' + name);
    });
  });

  document.querySelectorAll('[data-agent-delete]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var card = btn.closest('.agent-card');
      if (!card) return;
      var nameEl = card.querySelector('.agent-name');
      var name = nameEl ? nameEl.textContent : '该智能体';
      openConfirm('删除智能体？', '将从注册表移除「' + name + '」，其技能不再出现在工具目录；历史任务记录保留。', function () {
        card.remove();
        updateAgentStats();
        filterAgents();
        showToast('已删除 ' + name);
      }, '删除智能体');
    });
  });

