VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}

class Check(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]; self.ids={}; self.dups=[]; self.hrefs=[]; self.controls=[]; self.uses=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs); ln=self.getpos()[0]
        if 'id' in d:
            if d['id'] in self.ids: self.dups.append((d['id'], self.ids[d['id']], ln))
            else: self.ids[d['id']]=ln
        if tag=='a' and 'href' in d: self.hrefs.append((d['href'], ln))
        if 'aria-controls' in d: self.controls.append((d['aria-controls'], ln))
        if tag=='use' and 'href' in d: self.uses.append((d['href'], ln))
        if 'aria-labelledby' in d:
            for ref in d['aria-labelledby'].split(): self.controls.append((ref, ln))
        if tag not in VOID:
            self.stack.append((tag, ln))
    def handle_startendtag(self, tag, attrs):
        d=dict(attrs); ln=self.getpos()[0]
        if 'id' in d:
            if d['id'] in self.ids: self.dups.append((d['id'], self.ids[d['id']], ln))
            else: self.ids[d['id']]=ln
    def handle_endtag(self, tag):
        if tag in VOID: return
        ln=self.getpos()[0]
        if not self.stack:
            self.errors.append(f'line {ln}: unexpected </{tag}>'); return
        if self.stack[-1][0]==tag:
            self.stack.pop()
        else:
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag:
                    unclosed=[t for t,_ in self.stack[i+1:]]
                    self.errors.append(f'line {ln}: </{tag}> closes over unclosed {unclosed}')
                    del self.stack[i:]
                    break
            else:
                self.errors.append(f'line {ln}: stray </{tag}>')

def check_html(path):
    txt=open(path, encoding='utf-8').read()
    p=Check(); p.feed(txt)
    print(f'\n=== {os.path.basename(path)} ===')
    print('duplicate ids:', len(p.dups), p.dups[:10])
    print('unclosed tags:', len(p.stack), p.stack[:10])
    print('tag errors:', len(p.errors), p.errors[:10])
    symbols=set(re.findall(r'<symbol[^>]*\bid="([^"]+)"', txt))
    missing_use=[(h,l) for h,l in p.uses if h.startswith('#') and h[1:] not in symbols and h[1:] not in p.ids]
    print('missing <use> targets:', len(missing_use), missing_use[:10])
    missing_controls=[(c,l) for c,l in p.controls if c not in p.ids]
    print('missing aria-controls/labelledby:', len(missing_controls), missing_controls[:10])
    missing_hashes=[(h,l) for h,l in p.hrefs if h.startswith('#') and len(h)>1 and h[1:] not in p.ids]
    print('missing local hashes:', len(missing_hashes), missing_hashes[:10])

for f in ['docs/prototypes/ui-v7.html','docs/prototypes/ui-v7-pages.html','docs/prototypes/ui-v8-admin.html']:
    check_html(f)
