    print(f'{os.path.basename(f)}: dups={len(p.dups)} unclosed={len(p.stack)} tagErr={len(p.err)} useMissing={len(use_missing)} ctlMissing={len(ctl_missing)} js={"OK" if r.returncode==0 else "FAIL"} cssBraces={css.count("{")}/{css.count("}")} undefinedVars={sorted(used-defined)}')
