import re, os, subprocess, tempfile
from html.parser import HTMLParser
VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class C(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.err=[]; self.ids={}; self.dups=[]; self.uses=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if 'id' in d:
            if d['id'] in self.ids: self.dups.append(d['id'])
            else: self.ids[d['id']]=1
        if t=='use' and 'href' in d: self.uses.append(d['href'])
        if t not in VOID: self.stack.append(t)
    def handle_endtag(self,t):
        if t in VOID: return
        if self.stack and self.stack[-1]==t: self.stack.pop()
        elif t in self.stack:
            i=len(self.stack)-1-self.stack[::-1].index(t); self.err.append(t); del self.stack[i:]
        else: self.err.append(t)
txt=open('docs/prototypes/ui-v7.html',encoding='utf-8').read(); p=C(); p.feed(txt)
symbols=set(re.findall(r'<symbol[^>]*\bid="([^"]+)"',txt))
use_missing=[u for u in p.uses if u.startswith('#') and u[1:] not in symbols and u[1:] not in p.ids]
js='\n'.join(re.findall(r'<script[^>]*>(.*?)</script>',txt,re.S))
t=tempfile.NamedTemporaryFile('w',suffix='.js',delete=False,encoding='utf-8'); t.write(js); t.close()
r=subprocess.run(['node','--check',t.name],capture_output=True,text=True); os.unlink(t.name)
css='\n'.join(re.findall(r'<style[^>]*>(.*?)</style>',txt,re.S))
print('dups',len(p.dups),'unclosed',len(p.stack),'tagErr',len(p.err),'useMissing',len(use_missing),'js',r.returncode==0,'braces',css.count('{'),css.count('}'))
print('stopBtn refs:', txt.count('stopBtn'))
print('is-stop refs:', txt.count('is-stop'))
